// src/decodificar.ts
var CAMPOS_EI = {
  EO: "O eu, o outro e o n\xF3s",
  CG: "Corpo, gestos e movimentos",
  TS: "Tra\xE7os, sons, cores e formas",
  EF: "Escuta, fala, pensamento e imagina\xE7\xE3o",
  ET: "Espa\xE7os, tempos, quantidades, rela\xE7\xF5es e transforma\xE7\xF5es"
};
var GRUPOS_EI = {
  "01": "Beb\xEAs (0\u20131a6m)",
  "02": "Crian\xE7as bem pequenas (1a7m\u20133a11m)",
  "03": "Crian\xE7as pequenas (4a\u20135a11m)"
};
var COMPONENTES_EF = {
  AR: "Arte",
  CI: "Ci\xEAncias",
  EF: "Educa\xE7\xE3o F\xEDsica",
  ER: "Ensino Religioso",
  GE: "Geografia",
  HI: "Hist\xF3ria",
  LI: "L\xEDngua Inglesa",
  LP: "L\xEDngua Portuguesa",
  MA: "Matem\xE1tica"
};
var BLOCOS_EF = {
  "15": [1, 2, 3, 4, 5],
  "69": [6, 7, 8, 9],
  "12": [1, 2],
  "35": [3, 4, 5],
  "67": [6, 7],
  "89": [8, 9]
};
var BLOCOS_VALIDOS_POR_COMPONENTE = {
  AR: /* @__PURE__ */ new Set(["15", "69"]),
  LP: /* @__PURE__ */ new Set(["15", "69", "12", "35", "67", "89"]),
  EF: /* @__PURE__ */ new Set(["12", "35", "67", "89"])
};
var AREAS_EM = {
  LGG: "Linguagens e suas Tecnologias",
  MAT: "Matem\xE1tica e suas Tecnologias",
  CNT: "Ci\xEAncias da Natureza e suas Tecnologias",
  CHS: "Ci\xEAncias Humanas e Sociais Aplicadas"
};
function decodificar(codigoBruto) {
  const codigo = codigoBruto.trim().toUpperCase();
  let m = codigo.match(/^EI(0[123])(EO|CG|TS|EF|ET)(\d{2})$/);
  if (m) {
    const [, grupo, campo, seq] = m;
    return {
      codigo,
      etapa: "EI",
      grupoEtario: grupo,
      grupoEtarioNome: GRUPOS_EI[grupo],
      campoExperiencias: campo,
      campoExperienciasNome: CAMPOS_EI[campo],
      sequencia: Number(seq)
    };
  }
  m = codigo.match(/^EF(\d{2})([A-Z]{2})(\d{2})$/);
  if (m) {
    const [, anosStr, comp, seq] = m;
    if (!(comp in COMPONENTES_EF)) throw new Error(`${codigo}: componente '${comp}' desconhecido`);
    let anos;
    if (anosStr in BLOCOS_EF) {
      if (!BLOCOS_VALIDOS_POR_COMPONENTE[comp]?.has(anosStr)) {
        throw new Error(`${codigo}: bloco '${anosStr}' inv\xE1lido para ${COMPONENTES_EF[comp]}`);
      }
      anos = BLOCOS_EF[anosStr];
    } else if (anosStr.startsWith("0") && Number(anosStr) >= 1 && Number(anosStr) <= 9) {
      anos = [Number(anosStr)];
    } else {
      throw new Error(`${codigo}: ano/bloco '${anosStr}' inv\xE1lido`);
    }
    return {
      codigo,
      etapa: "EF",
      anos,
      bloco: anosStr in BLOCOS_EF,
      componente: comp,
      componenteNome: COMPONENTES_EF[comp],
      sequencia: Number(seq)
    };
  }
  m = codigo.match(/^EM13([A-Z]{3})(\d)(\d{2})$/);
  if (m && m[1] in AREAS_EM) {
    const [, area, ce, seq] = m;
    return {
      codigo,
      etapa: "EM",
      seriacao: null,
      area,
      areaNome: AREAS_EM[area],
      competenciaEspecifica: Number(ce),
      sequencia: Number(seq)
    };
  }
  m = codigo.match(/^EM13LP(\d{2})$/);
  if (m) {
    return {
      codigo,
      etapa: "EM",
      seriacao: null,
      area: "LGG",
      areaNome: AREAS_EM.LGG,
      componente: "LP",
      competenciaEspecifica: null,
      sequencia: Number(m[1])
    };
  }
  throw new Error(`${codigo}: n\xE3o corresponde a nenhuma gram\xE1tica BNCC (EI/EF/EM)`);
}

// src/nucleo.ts
function normalizarTexto(t) {
  return t.normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase().replace(/\s+/g, " ").trim();
}
function criarConsultas(dados) {
  const estruturaDados = dados.estrutura;
  const ei = dados.educacaoInfantil;
  const ef = dados.ensinoFundamental;
  const em = dados.ensinoMedio;
  const porCodigoMapa = /* @__PURE__ */ new Map();
  for (const o of ei.objetivos) porCodigoMapa.set(o.codigo, o);
  for (const h of ef.habilidades) porCodigoMapa.set(h.codigo, h);
  for (const h of em.habilidades) porCodigoMapa.set(h.codigo, h);
  const contextos = /* @__PURE__ */ new Map();
  for (const c of [...ef.contextos_organizacao, ...em.contextos_organizacao]) contextos.set(c.id, c);
  const competenciasPorId = new Map(estruturaDados.competencias_especificas.map((c) => [c.id, c]));
  const alinhamentoPorId = new Map(ei.alinhamentos.map((a) => [a.id, a]));
  const nomesComponentes = new Map(estruturaDados.componentes_curriculares.map((c) => [c.id, c.nome]));
  const nomesAreas = new Map(estruturaDados.areas_conhecimento.map((a) => [a.id, a.nome]));
  const nomesCampos = new Map(estruturaDados.campos_experiencias.map((c) => [c.id, c.nome]));
  function resolverNome(id) {
    return contextos.get(id)?.nome ?? nomesComponentes.get(id) ?? nomesAreas.get(id) ?? nomesCampos.get(id) ?? id;
  }
  function resolver(reg) {
    const etapa = decodificar(reg.codigo).etapa;
    const base = { codigo: reg.codigo, etapa, texto: reg.texto, vigencia: reg.vigencia, fonte: reg.fonte };
    if (etapa === "EI") {
      const o = reg;
      return {
        ...base,
        campoExperiencias: { id: o.campo_experiencias, nome: nomesCampos.get(o.campo_experiencias) ?? o.campo_experiencias },
        grupoEtario: o.grupo_etario,
        alinhamento: o.alinhamento
      };
    }
    if (etapa === "EF") {
      const h2 = reg;
      const nomes = {};
      if ("unidade_tematica" in h2.organizacao) nomes.unidadeTematica = resolverNome(h2.organizacao.unidade_tematica);
      if (h2.organizacao.tipo === "campo_pratica") {
        nomes.camposAtuacao = h2.organizacao.campos_atuacao.map(resolverNome);
        nomes.praticaLinguagem = resolverNome(h2.organizacao.pratica_linguagem);
      }
      if (h2.organizacao.tipo === "eixo") nomes.eixo = resolverNome(h2.organizacao.eixo);
      return {
        ...base,
        componente: { id: h2.componente, nome: nomesComponentes.get(h2.componente) ?? h2.componente },
        anos: h2.anos,
        organizacao: { tipo: h2.organizacao.tipo, nomes },
        objetosConhecimento: h2.objetos_conhecimento.map((id) => ({ id, nome: resolverNome(id) }))
      };
    }
    const h = reg;
    return {
      ...base,
      area: { id: h.area, nome: nomesAreas.get(h.area) ?? h.area },
      componente: h.componente ? { id: h.componente, nome: nomesComponentes.get(h.componente) ?? h.componente } : null,
      competenciasEspecificas: h.competencias_especificas.map((id) => {
        const c = competenciasPorId.get(id);
        return { id, numero: c?.numero ?? 0, texto: c?.texto ?? "" };
      }),
      camposAtuacaoSocial: h.campos_atuacao_social?.map((id) => ({ id, nome: resolverNome(id) }))
    };
  }
  function porCodigo(codigo) {
    const cod = codigo.trim().toUpperCase();
    const reg = porCodigoMapa.get(cod);
    if (!reg) {
      decodificar(cod);
      throw new Error(`${cod}: c\xF3digo v\xE1lido na forma, mas n\xE3o existe na BNCC (dica: a numera\xE7\xE3o tem lacunas leg\xEDtimas)`);
    }
    return resolver(reg);
  }
  function habilidadesEF(filtro = {}) {
    const comp = filtro.componente && (filtro.componente.startsWith("ef-comp-") ? filtro.componente : `ef-comp-${filtro.componente.toLowerCase()}`);
    return ef.habilidades.filter((h) => !comp || h.componente === comp).filter((h) => !filtro.ano || h.anos.includes(filtro.ano)).filter((h) => !filtro.unidadeTematica || "unidade_tematica" in h.organizacao && resolverNome(h.organizacao.unidade_tematica) === filtro.unidadeTematica).filter((h) => !filtro.pratica || h.organizacao.tipo === "campo_pratica" && resolverNome(h.organizacao.pratica_linguagem) === filtro.pratica).filter((h) => !filtro.campoAtuacao || h.organizacao.tipo === "campo_pratica" && h.organizacao.campos_atuacao.some((c) => resolverNome(c) === filtro.campoAtuacao)).map(resolver);
  }
  function habilidadesEM(filtro = {}) {
    const area = filtro.area && (filtro.area.startsWith("em-area-") ? filtro.area : `em-area-${filtro.area.toLowerCase()}`);
    return em.habilidades.filter((h) => !area || h.area === area).filter((h) => !filtro.apenasLP || h.componente === "em-comp-lp").filter((h) => !filtro.competencia || h.competencias_especificas.some((id) => competenciasPorId.get(id)?.numero === filtro.competencia)).map(resolver);
  }
  function objetivosEI(filtro = {}) {
    const campo = filtro.campo && (filtro.campo.startsWith("ei-campo-") ? filtro.campo : `ei-campo-${filtro.campo.toLowerCase()}`);
    const grupo = filtro.grupoEtario && (filtro.grupoEtario.startsWith("ei-grupo-") ? filtro.grupoEtario : `ei-grupo-${filtro.grupoEtario}`);
    return ei.objetivos.filter((o) => !campo || o.campo_experiencias === campo).filter((o) => !grupo || o.grupo_etario === grupo).map(resolver);
  }
  function buscar(texto, filtro = {}) {
    const alvo = normalizarTexto(texto);
    const universo = [
      ...!filtro.etapa || filtro.etapa === "EI" ? ei.objetivos : [],
      ...!filtro.etapa || filtro.etapa === "EF" ? ef.habilidades : [],
      ...!filtro.etapa || filtro.etapa === "EM" ? em.habilidades : []
    ];
    const comp = filtro.componente && (filtro.componente.includes("-comp-") ? filtro.componente : `ef-comp-${filtro.componente.toLowerCase()}`);
    return universo.filter((r) => normalizarTexto(r.texto).includes(alvo)).filter((r) => !comp || "componente" in r && r.componente === comp).filter((r) => !filtro.ano || "anos" in r && r.anos.includes(filtro.ano)).map(resolver);
  }
  function progressaoEI(codigo) {
    const reg = porCodigo(codigo);
    if (reg.etapa !== "EI") throw new Error(`${reg.codigo}: progress\xE3o por alinhamento s\xF3 existe na Educa\xE7\xE3o Infantil`);
    const al = alinhamentoPorId.get(reg.alinhamento);
    if (!al) throw new Error(`${reg.codigo}: alinhamento ${reg.alinhamento} n\xE3o encontrado`);
    return { alinhamento: al.id, objetivos: al.objetivos.map(porCodigo), nota: al.nota };
  }
  function estrutura() {
    return estruturaDados;
  }
  function estatisticas() {
    return {
      total: ei.objetivos.length + ef.habilidades.length + em.habilidades.length,
      educacaoInfantil: ei.objetivos.length,
      ensinoFundamental: ef.habilidades.length,
      ensinoMedio: em.habilidades.length,
      alinhamentosEI: ei.alinhamentos.length,
      competenciasGerais: estruturaDados.competencias_gerais.length,
      competenciasEspecificas: estruturaDados.competencias_especificas.length
    };
  }
  return { porCodigo, habilidadesEF, habilidadesEM, objetivosEI, buscar, progressaoEI, estrutura, estatisticas };
}

export {
  CAMPOS_EI,
  GRUPOS_EI,
  COMPONENTES_EF,
  BLOCOS_EF,
  AREAS_EM,
  decodificar,
  normalizarTexto,
  criarConsultas
};
