// src/tools.ts
import { z } from "zod";
import { decodificar } from "@bncc/dados/nucleo";
var json = (dados) => ({ content: [{ type: "text", text: JSON.stringify(dados, null, 1) }] });
var erro = (e) => ({
  content: [{ type: "text", text: JSON.stringify({ erro: e instanceof Error ? e.message : String(e) }) }],
  isError: true
});
function compacto(r) {
  return {
    codigo: r.codigo,
    etapa: r.etapa,
    texto: r.texto,
    ...r.componente ? { componente: r.componente.nome } : {},
    ...r.area ? { area: r.area.nome } : {},
    ...r.anos ? { anos: r.anos } : {},
    ...r.campoExperiencias ? { campo: r.campoExperiencias.nome, grupo: r.grupoEtario } : {}
  };
}
function limitar(itens, limite) {
  return { total: itens.length, exibindo: Math.min(itens.length, limite), resultados: itens.slice(0, limite) };
}
function instrucoesServidor(bncc, dataVersion) {
  const total = bncc.estatisticas().total.toLocaleString("pt-BR");
  return `Dados oficiais e verificados da BNCC (Base Nacional Comum Curricular brasileira): ${total} aprendizagens das tr\xEAs etapas, cada uma com fonte oficial (p\xE1gina do PDF homologado).
Regras: (1) nunca invente c\xF3digos ou textos de habilidade; se um c\xF3digo n\xE3o est\xE1 nos dados, ele n\xE3o existe na BNCC; (2) a numera\xE7\xE3o tem lacunas leg\xEDtimas; (3) ao citar uma aprendizagem para o usu\xE1rio, inclua o c\xF3digo e, quando relevante, a fonte.
Etapas: EI (objetivos por campo de experi\xEAncias e grupo et\xE1rio), EF (habilidades por componente e ano), EM (habilidades por \xE1rea, sem seria\xE7\xE3o). C\xF3digos: EI02TS01, EF67LP08, EM13LGG103.
Vers\xE3o dos dados: ${dataVersion}.`;
}
function registrarTools(servidor, bncc, versao) {
  servidor.registerTool("bncc_lookup", {
    title: "Buscar aprendizagem por c\xF3digo",
    description: 'Retorna o registro completo e verificado de uma aprendizagem da BNCC pelo c\xF3digo (ex.: "EF67LP08", "EI02TS01", "EM13LGG103"; aceita min\xFAsculas). Inclui texto oficial, contexto pedag\xF3gico resolvido (componente, unidade tem\xE1tica/pr\xE1tica, objetos de conhecimento, compet\xEAncias) e a fonte oficial com p\xE1gina do PDF homologado. Use sempre que o usu\xE1rio mencionar um c\xF3digo ou quando precisar do enunciado exato: nunca cite de mem\xF3ria.',
    inputSchema: { codigo: z.string().describe("C\xF3digo BNCC, ex.: EF67LP08") }
  }, async ({ codigo }) => {
    try {
      return json(bncc.porCodigo(codigo));
    } catch (e) {
      return erro(e);
    }
  });
  servidor.registerTool("bncc_buscar", {
    title: "Busca textual nos enunciados",
    description: 'Busca um termo nos textos oficiais das aprendizagens (normalizada: acentos e mai\xFAsculas n\xE3o importam). Use para encontrar habilidades sobre um tema (ex.: texto="fra\xE7\xF5es", componente="MA"). Retorna {total, exibindo, resultados}; se total > exibindo, refine os filtros ou aumente o limite. Componentes do EF: LP, AR, EF, LI, MA, CI, GE, HI, ER.',
    inputSchema: {
      texto: z.string().describe("Termo a buscar nos enunciados"),
      etapa: z.enum(["EI", "EF", "EM"]).optional(),
      componente: z.string().optional().describe("Sigla do componente do EF, ex.: MA, LP"),
      ano: z.number().int().min(1).max(9).optional(),
      limite: z.number().int().min(1).max(100).default(20)
    }
  }, async ({ texto, etapa, componente, ano, limite }) => {
    try {
      return json(limitar(bncc.buscar(texto, { etapa, componente, ano }).map(compacto), limite));
    } catch (e) {
      return erro(e);
    }
  });
  servidor.registerTool("bncc_listar", {
    title: "Listar aprendizagens por filtros estruturados",
    description: 'Lista aprendizagens de uma etapa com filtros estruturados (sem busca textual). EF: componente (sigla, ex.: LP) e/ou ano (1-9). EM: area (LGG, MAT, CNT, CHS) e/ou competencia (n\xFAmero) e/ou apenas_lp. EI: campo (EO, CG, TS, EF, ET) e/ou grupo_etario (01, 02, 03). Use para cobertura curricular ("todas as habilidades do 4\xBA ano de Matem\xE1tica") e navega\xE7\xE3o. Retorna {total, exibindo, resultados}.',
    inputSchema: {
      etapa: z.enum(["EI", "EF", "EM"]),
      componente: z.string().optional().describe("EF: sigla do componente (LP, MA, CI...)"),
      ano: z.number().int().min(1).max(9).optional().describe("EF: ano"),
      area: z.string().optional().describe("EM: LGG, MAT, CNT ou CHS"),
      competencia: z.number().int().optional().describe("EM: n\xFAmero da compet\xEAncia espec\xEDfica da \xE1rea"),
      apenas_lp: z.boolean().optional().describe("EM: s\xF3 habilidades de L\xEDngua Portuguesa"),
      campo: z.string().optional().describe("EI: sigla do campo de experi\xEAncias (EO, CG, TS, EF, ET)"),
      grupo_etario: z.string().optional().describe("EI: 01 (beb\xEAs), 02 (bem pequenas), 03 (pequenas)"),
      limite: z.number().int().min(1).max(200).default(50)
    }
  }, async ({ etapa, componente, ano, area, competencia, apenas_lp, campo, grupo_etario, limite }) => {
    try {
      const itens = etapa === "EF" ? bncc.habilidadesEF({ componente, ano }) : etapa === "EM" ? bncc.habilidadesEM({ area, competencia, apenasLP: apenas_lp }) : bncc.objetivosEI({ campo, grupoEtario: grupo_etario });
      return json(limitar(itens.map(compacto), limite));
    } catch (e) {
      return erro(e);
    }
  });
  servidor.registerTool("bncc_decodificar", {
    title: "Decodificar a estrutura de um c\xF3digo",
    description: "Explica a anatomia de um c\xF3digo BNCC sem consultar o dataset: etapa, ano(s) ou bloco, componente/\xE1rea, compet\xEAncia embutida (EM) e sequ\xEAncia. Funciona para qualquer c\xF3digo gramaticalmente v\xE1lido, mesmo que n\xE3o exista (aten\xE7\xE3o: exist\xEAncia se confere com bncc_lookup). Use para validar/explicar c\xF3digos que o usu\xE1rio digitou.",
    inputSchema: { codigo: z.string().describe("C\xF3digo BNCC a decodificar") }
  }, async ({ codigo }) => {
    try {
      return json(decodificar(codigo));
    } catch (e) {
      return erro(e);
    }
  });
  servidor.registerTool("bncc_progressao_ei", {
    title: "Progress\xE3o da Educa\xE7\xE3o Infantil entre faixas et\xE1rias",
    description: "Dado um objetivo da Educa\xE7\xE3o Infantil (ex.: EI02TS01), retorna os objetivos do MESMO aspecto nas tr\xEAs faixas et\xE1rias (beb\xEAs, crian\xE7as bem pequenas, crian\xE7as pequenas) \u2014 o alinhamento horizontal oficial da BNCC (p. 26). Use para planejar continuidade/adapta\xE7\xE3o entre faixas. S\xF3 existe para c\xF3digos EI.",
    inputSchema: { codigo: z.string().describe("C\xF3digo EI, ex.: EI02TS01") }
  }, async ({ codigo }) => {
    try {
      return json(bncc.progressaoEI(codigo));
    } catch (e) {
      return erro(e);
    }
  });
  servidor.registerTool("bncc_estrutura", {
    title: "Estrutura do sistema educacional",
    description: "Retorna as cole\xE7\xF5es estruturais da BNCC: etapas, \xE1reas do conhecimento, componentes curriculares (com quem tem habilidades pr\xF3prias), compet\xEAncias gerais (10), compet\xEAncias espec\xEDficas (105), recortes temporais, campos de experi\xEAncias e modalidades (EJA). Sem argumento, retorna o \xEDndice de cole\xE7\xF5es dispon\xEDveis com contagens.",
    inputSchema: {
      colecao: z.enum([
        "etapas",
        "areas_conhecimento",
        "componentes_curriculares",
        "competencias_gerais",
        "competencias_especificas",
        "recortes_temporais",
        "campos_experiencias",
        "modalidades"
      ]).optional()
    }
  }, async ({ colecao }) => {
    try {
      const e = bncc.estrutura();
      if (!colecao) {
        return json(Object.fromEntries(Object.entries(e).map(([k, v]) => [k, Array.isArray(v) ? v.length : v])));
      }
      return json(e[colecao]);
    } catch (er) {
      return erro(er);
    }
  });
  servidor.registerTool("bncc_estatisticas", {
    title: "Contagens e vers\xE3o do dataset",
    description: "Contagens do dataset (total de aprendizagens por etapa, compet\xEAncias, alinhamentos) e a vers\xE3o dos dados embutidos (data-version, commit de origem). Use para sanidade e para citar a vers\xE3o do dado.",
    inputSchema: {}
  }, async () => {
    try {
      return json({ ...bncc.estatisticas(), versao });
    } catch (e) {
      return erro(e);
    }
  });
}

export {
  instrucoesServidor,
  registrarTools
};
